<?php
namespace App\Http\Requests\Api; use Illuminate\Foundation\Http\FormRequest; use Illuminate\Validation\Rule;
class DeviceRequest extends FormRequest {public function authorize():bool{return true;}public function rules():array{$id=$this->route('device')?->id;return ['controller_id'=>'required|exists:tn_controllers,id','device_code'=>['required','string','max:80',Rule::unique('controller_devices')->ignore($id)],'device_name'=>'required|string|max:255','device_type'=>['required',Rule::in(['Thermocouple'])],'sensor_type'=>['nullable',Rule::in(['K','J','PT100'])],'unit'=>'required|string|max:20','register_pv'=>'nullable|integer|min:0','register_sv'=>'nullable|integer|min:0','register_output'=>'nullable|integer|min:0','register_alarm'=>'nullable|integer|min:0','status'=>['required',Rule::in(['Active','Inactive'])]];}}
